Track opening-parenthesis indices in a stack with an initial boundary of −1. After matching a closing parenthesis, the distance from the remaining top gives the longest valid substring ending there; an unmatched closing parenthesis resets the boundary.

```javascript
function solve(s) {
  const stack = [-1];
  let longest = 0;

  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      stack.push(i);
    } else {
      stack.pop();
      if (stack.length === 0) {
        stack.push(i);
      } else {
        longest = Math.max(longest, i - stack[stack.length - 1]);
      }
    }
  }

  return longest;
}
```

